package com.citacloud.app.models;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="facturas") public class Factura { @Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false) private UUID empresaId; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="paciente_id") private Paciente paciente; private String numero; private LocalDate fecha; private BigDecimal subtotal=BigDecimal.ZERO, descuento=BigDecimal.ZERO, impuestos=BigDecimal.ZERO,total=BigDecimal.ZERO; @Column(name="monto_pagado") private BigDecimal montoPagado=BigDecimal.ZERO; private BigDecimal saldo=BigDecimal.ZERO; private String estado="BORRADOR";
 public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public Paciente getPaciente(){return paciente;} public void setPaciente(Paciente v){paciente=v;} public String getNumero(){return numero;} public void setNumero(String v){numero=v;} public LocalDate getFecha(){return fecha;} public void setFecha(LocalDate v){fecha=v;} public BigDecimal getSubtotal(){return subtotal;} public void setSubtotal(BigDecimal v){subtotal=v;} public BigDecimal getDescuento(){return descuento;} public void setDescuento(BigDecimal v){descuento=v;} public BigDecimal getImpuestos(){return impuestos;} public void setImpuestos(BigDecimal v){impuestos=v;} public BigDecimal getTotal(){return total;} public void setTotal(BigDecimal v){total=v;} public BigDecimal getMontoPagado(){return montoPagado;} public void setMontoPagado(BigDecimal v){montoPagado=v;} public BigDecimal getSaldo(){return saldo;} public void setSaldo(BigDecimal v){saldo=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} }
